n': 'Reconcile the converted data with Oracle EBS', 'action': 'reconcile', 'target': 'reconciliation reports', 'parallel_group': None, 'preconditions': [], 'verification': {'what': 'financial totals and key reports', 'how': 'compare records between systems', 'expected': 'no discrepancies in totals'}, 'rollback': {'trigger': 'discrepancies found', 'action': 're-examine conversion logs', 'safety_guard': 'document discrepancies for review', 'restores_state': None, 'restoration_evidence': None}, 'risk_class': 'high', 'blast_radius': 'medium', 'satisfies': None}, {'id': 'verify_conversion', 'description': 'Business users validate sample records and run trial balance', 'action': 'validate', 'target': 'final conversion', 'parallel_group': None, 'preconditions': [], 'verification': {'what': 'user acceptance of records', 'how': 'random sampling and trial balance', 'expected': 'all users approve the sample records'}, 'rollback': {'trigger': 'validation fails', 'action': 'reset to pre-conversion state', 'safety_guard': 'confirm user satisfaction with pre-state', 'restores_state': None, 'restoration_evidence': None}, 'risk_class': 'high', 'blast_radius': 'medium', 'satisfies': None}], 'dependencies': [{'from_task': 'extract_data', 'to_task': 'transform_validate', 'kind': 'hard', 'reason': ''}, {'from_task': 'transform_validate', 'to_task': 'map_migrate', 'kind': 'hard', 'reason': ''}, {'from_task': 'map_migrate', 'to_task': 'reconcile_data', 'kind': 'hard', 'reason': ''}, {'from_task': 'reconcile_data', 'to_task': 'verify_conversion', 'kind': 'hard', 'reason': ''}], 'branches': []}

